<?php
include 'includes/cek_session.php';include 'config/koneksi.php';$embed=(($_GET['embed']??'')==='1');$q=mysqli_query($koneksi,"SELECT id,tanggal,nama_siswa,nama_kelas,nama_pelanggaran,poin,tindakan,status,nama_guru FROM t_pelanggaran_siswa ORDER BY tanggal DESC,id DESC");if(!$q)die('Gagal mengambil data: '.htmlspecialchars(mysqli_error($koneksi)));function eT($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?>
<?php if(!$embed):?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tindakan Pelanggaran</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php endif;?>
<main class="container-fluid p-3 p-md-4 bg-white"><h2 class="fw-bold">Tindakan Pelanggaran</h2><p class="text-secondary">Isi tindak lanjut pembinaan dan perbarui status penanganan setiap catatan.</p><?php if(!empty($_SESSION['pesan'])):?><div class="alert alert-info alert-dismissible fade show"><?=eT($_SESSION['pesan'])?><button type="button" class="btn-close" data-bs-dismiss="alert"></button></div><?php unset($_SESSION['pesan']);endif;?>
<div class="table-responsive"><table class="table table-bordered table-hover align-middle"><thead class="table-light"><tr><th>No</th><th>Tanggal</th><th>Siswa / Kelas</th><th>Pelanggaran</th><th>Poin</th><th>Guru</th><th style="min-width:300px">Tindakan & Status</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($q)):?><tr><td><form id="tindakan<?=(int)$r['id']?>" method="post" action="proses_tindakan.php"></form><input form="tindakan<?=(int)$r['id']?>" type="hidden" name="id" value="<?=(int)$r['id']?>"><input form="tindakan<?=(int)$r['id']?>" type="hidden" name="embed" value="<?=$embed?'1':'0'?>"><?=$no++?></td><td><?=eT($r['tanggal'])?></td><td><strong><?=eT($r['nama_siswa'])?></strong><br><small class="text-muted"><?=eT($r['nama_kelas'])?></small></td><td><?=eT($r['nama_pelanggaran'])?></td><td><span class="badge text-bg-danger"><?=(int)$r['poin']?></span></td><td><?=eT($r['nama_guru'])?></td><td><textarea form="tindakan<?=(int)$r['id']?>" name="tindakan" class="form-control form-control-sm mb-2" rows="2" required placeholder="Isi tindakan pembinaan..."><?=eT($r['tindakan'])?></textarea><select form="tindakan<?=(int)$r['id']?>" name="status" class="form-select form-select-sm"><option value="Belum ditindaklanjuti" <?=$r['status']==='Belum ditindaklanjuti'?'selected':''?>>Belum ditindaklanjuti</option><option value="Dalam proses" <?=$r['status']==='Dalam proses'?'selected':''?>>Dalam proses</option><option value="Selesai" <?=$r['status']==='Selesai'?'selected':''?>>Selesai</option></select></td><td><button form="tindakan<?=(int)$r['id']?>" class="btn btn-sm btn-primary" type="submit">Simpan</button></td></tr><?php endwhile;?><?php if(mysqli_num_rows($q)===0):?><tr><td colspan="8" class="text-center text-muted py-4">Belum ada catatan pelanggaran.</td></tr><?php endif;?></tbody></table></div></main><?php if(!$embed):?></body></html><?php endif;?>
